                        GUILayout.Space(5);
                    }

                    if (!integration.installed)
                    {
                        //UI.DrawNotification("Shader library for asset not found in project", MessageType.Error);
                    }
                }
                EditorGUILayout.EndVertical();
            }
            EditorGUILayout.EndHorizontal();
